package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import org.eclipse.kura.KuraException;
import org.eclipse.kura.core.testutil.TestUtil;
import org.eclipse.kura.linux.watchdog.WatchdogServiceOptions.WatchdogMode;
import org.eclipse.kura.watchdog.CriticalComponent;
import org.eclipse.kura.watchdog.WatchdogState;
import org.junit.After;
import org.junit.Test;

public class BackendSelectionTest {

    private static final String TEST_DEVICE = "target/backendSelectionDevice";
    private static final String MISSING_DEVICE = "target/backendSelectionMissingDevice";
    private static final String REBOOT_CAUSE_FILE = "target/backendSelectionRebootCause";

    private final File markerFile = new File(
            new WatchdogServiceOptions(new HashMap<>()).getWatchdogEnabledTemporaryFilePath());

    private final RecordingWatchdogDevice device = new RecordingWatchdogDevice();
    private SelectionWatchdogServiceImpl svc;

    @Test
    public void disabledServiceLeavesWatchdogUntouched() throws Throwable {
        givenService();

        whenServiceIsActivated(false, "direct", TEST_DEVICE);

        thenNoBackendIsActive();
        thenWatchdogStateIs(WatchdogState.DISABLED);
        thenNothingIsWrittenToTheDevice();
    }

    @Test
    public void directBackendIsActiveWhenDeviceIsAvailable() throws Throwable {
        givenService();

        whenServiceIsActivated(true, "direct", TEST_DEVICE);

        thenActiveModeIs(WatchdogMode.DIRECT);
        thenWatchdogStateIs(WatchdogState.SUPERVISING);
    }

    @Test
    public void fallbackBackendActivatesWhenDeviceIsMissing() throws Throwable {
        givenService();

        whenServiceIsActivated(true, "direct", MISSING_DEVICE);

        thenActiveModeIs(WatchdogMode.FALLBACK);
        thenWatchdogStateIs(WatchdogState.DEVICE_UNAVAILABLE);
        thenNothingIsWrittenToTheDevice();
    }

    @Test
    public void systemdModeFallsBackWhenNotifySocketIsMissing() throws Throwable {
        givenService();

        whenServiceIsActivated(true, "systemd", TEST_DEVICE);

        thenActiveModeIs(WatchdogMode.FALLBACK);
        thenWatchdogStateIs(WatchdogState.DEVICE_UNAVAILABLE);
        thenNothingIsWrittenToTheDevice();
        thenMarkerFileDoesNotExist();
    }

    @Test
    public void fallbackBackendTakesOverWhenDeviceDisappearsOnReconfiguration() throws Throwable {
        givenService();
        givenServiceActivated(true, "direct", TEST_DEVICE);

        whenServiceIsReconfigured(true, "direct", MISSING_DEVICE);

        thenActiveModeIs(WatchdogMode.FALLBACK);
        thenMarkerFileDoesNotExist();
    }

    @Test
    public void markerIsRemovedWhenSwitchingToAnotherMode() throws Throwable {
        givenService();
        givenServiceActivated(true, "direct", TEST_DEVICE);
        thenMarkerFileExists();

        whenServiceIsReconfigured(true, "fallback", TEST_DEVICE);

        thenActiveModeIs(WatchdogMode.FALLBACK);
        thenMarkerFileDoesNotExist();
    }

    @Test
    public void markerIsKeptWhenServiceIsDeactivated() throws Throwable {
        givenService();
        givenServiceActivated(true, "direct", TEST_DEVICE);

        whenServiceIsDeactivated();

        thenMarkerFileExists();
        thenDeviceIsClosedWithoutBeingDisarmed();
    }

    @Test
    public void staleMarkerIsRemovedWhenServiceStartsDisabled() throws Throwable {
        givenService();
        givenStaleMarkerFile();

        whenServiceIsActivated(false, "direct", TEST_DEVICE);

        thenMarkerFileDoesNotExist();
    }

    @Test
    public void deactivateDoesNotRequestAnotherRebootAfterCriticalComponentTimeout() throws Throwable {
        givenService();
        givenServiceActivated(true, "direct", TEST_DEVICE);
        givenCriticalComponentTimedOut();

        whenServiceIsDeactivated();

        thenRebootWasRequestedOnce();
    }

    @After
    public void cleanup() {
        if (this.svc != null) {
            this.svc.deactivate();
        }
        this.markerFile.delete();
        new File(REBOOT_CAUSE_FILE).delete();
    }

    private void givenService() {
        this.markerFile.delete();
        this.svc = new SelectionWatchdogServiceImpl();
    }

    private void givenServiceActivated(boolean enabled, String mode, String watchdogDevice) throws Throwable {
        whenServiceIsActivated(enabled, mode, watchdogDevice);
    }

    private void givenStaleMarkerFile() throws IOException {
        Files.write(this.markerFile.toPath(), TEST_DEVICE.getBytes(StandardCharsets.UTF_8));
    }

    private void givenCriticalComponentTimedOut() throws Throwable {
        this.svc.registerCriticalComponent(new CriticalComponent() {

            @Override
            public String getCriticalComponentName() {
                return "testComponent";
            }

            @Override
            public int getCriticalComponentTimeout() {
                return 0;
            }
        });
        final long deadline = System.currentTimeMillis() + 10000;
        while (this.svc.getRebootRequests() == 0 && System.currentTimeMillis() < deadline) {
            Thread.sleep(10);
        }
    }

    private void whenServiceIsActivated(boolean enabled, String mode, String watchdogDevice) throws Throwable {
        this.svc.activate(getProperties(enabled, mode, watchdogDevice));
        awaitPendingUpdate();
    }

    private void whenServiceIsReconfigured(boolean enabled, String mode, String watchdogDevice) throws Throwable {
        this.svc.updated(getProperties(enabled, mode, watchdogDevice));
        awaitPendingUpdate();
    }

    private void whenServiceIsDeactivated() {
        this.svc.deactivate();
    }

    private void thenNoBackendIsActive() throws NoSuchFieldException {
        assertEquals(Optional.empty(), TestUtil.getFieldValue(this.svc, "activeBackend"));
    }

    private void thenActiveModeIs(WatchdogMode expectedMode) throws NoSuchFieldException {
        final Optional<?> activeBackend = (Optional<?>) TestUtil.getFieldValue(this.svc, "activeBackend");
        assertEquals(Optional.of(expectedMode), activeBackend.map(backend -> ((WatchdogBackend) backend).getMode()));
    }

    private void thenWatchdogStateIs(WatchdogState expectedState) {
        assertEquals(expectedState, this.svc.getWatchdogStatus().getState());
    }

    private void thenNothingIsWrittenToTheDevice() {
        assertTrue(this.device.getWritten().isEmpty());
    }

    private void thenDeviceIsClosedWithoutBeingDisarmed() {
        assertTrue(this.device.isClosed());
        assertFalse(this.device.getWritten().contains("V"));
    }

    private void thenMarkerFileExists() {
        assertTrue(this.markerFile.exists());
    }

    private void thenMarkerFileDoesNotExist() {
        assertFalse(this.markerFile.exists());
    }

    private void thenRebootWasRequestedOnce() {
        assertEquals(1, this.svc.getRebootRequests());
    }

    private Map<String, Object> getProperties(boolean enabled, String mode, String watchdogDevice) {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", enabled);
        properties.put("watchdogMode", mode);
        properties.put("watchdogDevice", watchdogDevice);
        properties.put("pingInterval", 20);
        properties.put("rebootCauseFilePath", REBOOT_CAUSE_FILE);
        return properties;
    }

    private void awaitPendingUpdate() throws Exception {
        final ScheduledExecutorService pollExecutor = (ScheduledExecutorService) TestUtil.getFieldValue(this.svc,
                "pollExecutor");
        pollExecutor.submit(() -> {
        }).get(10, TimeUnit.SECONDS);
    }

    private class SelectionWatchdogServiceImpl extends HookedWatchdogServiceImpl {

        private int rebootRequests;

        @Override
        protected WatchdogDevice createWatchdogDevice(String watchdogDevice) {
            return BackendSelectionTest.this.device;
        }

        @Override
        protected boolean isWatchdogDeviceAvailable(String watchdogDevice) {
            return TEST_DEVICE.equals(watchdogDevice);
        }

        @Override
        protected synchronized void rebootSystem() throws KuraException {
            this.rebootRequests++;
        }

        synchronized int getRebootRequests() {
            return this.rebootRequests;
        }
    }
}
